  // A member is emitted as one or more PRIMITIVE pieces, each with a pure
  // translation in the member's own frame.  Nothing here is a boolean solid.
  //
  // shape 2 (filleted rectangular tube) is partitioned exactly into
  //   4 x G4Box  : the flat wall segments between the fillet tangent points
  //   4 x G4Tubs : the corner quarter-annuli, rmin = R - wall, rmax = R
  // Cold-formed HSS has concentric inner/outer fillets, so the flats end
  // exactly where the arcs begin: no gaps, no double counting.
  inline void MemberPieces(const Member& m, const G4String& nm,
                           std::vector<G4VSolid*>& solids,
                           std::vector<G4ThreeVector>& offsets)
  {
    const double hz = m.L / 2 * CLHEP::mm;

    if (m.shape == 1) {                                   // round pipe / bar
      double rOut = m.W1 / 2 * CLHEP::mm;
      double rIn  = (m.wall > 0.0) ? (m.W1 / 2 - m.wall) * CLHEP::mm : 0.0;
      solids.push_back(new G4Tubs(nm, rIn, rOut, hz, 0.0, CLHEP::twopi));
      offsets.push_back(G4ThreeVector(0, 0, 0));
      return;
    }

    if (m.shape == 2) {                                   // filleted rect tube
      const double a1 = m.W1 / 2, a2 = m.W2 / 2;
      const double t  = m.wall,   R  = m.rfil;
      const double f1 = a1 - R,   f2 = a2 - R;            // fillet centre offsets
      char b[192];
      // flat walls: +x, -x, +y, -y
      std::snprintf(b, sizeof(b), "%s_wx", nm.c_str());
      solids.push_back(new G4Box(G4String(b) + "p", t/2*CLHEP::mm, f2*CLHEP::mm, hz));
      offsets.push_back(G4ThreeVector((a1 - t/2)*CLHEP::mm, 0, 0));
      solids.push_back(new G4Box(G4String(b) + "m", t/2*CLHEP::mm, f2*CLHEP::mm, hz));
      offsets.push_back(G4ThreeVector(-(a1 - t/2)*CLHEP::mm, 0, 0));
      std::snprintf(b, sizeof(b), "%s_wy", nm.c_str());
      solids.push_back(new G4Box(G4String(b) + "p", f1*CLHEP::mm, t/2*CLHEP::mm, hz));
      offsets.push_back(G4ThreeVector(0, (a2 - t/2)*CLHEP::mm, 0));
      solids.push_back(new G4Box(G4String(b) + "m", f1*CLHEP::mm, t/2*CLHEP::mm, hz));
      offsets.push_back(G4ThreeVector(0, -(a2 - t/2)*CLHEP::mm, 0));
      // corner quarter-annuli, phi measured from +x in the member frame
      const double sx[4] = { +1, -1, -1, +1 };
      const double sy[4] = { +1, +1, -1, -1 };
      for (int k = 0; k < 4; ++k) {
        std::snprintf(b, sizeof(b), "%s_c%d", nm.c_str(), k);
        solids.push_back(new G4Tubs(b, (R - t)*CLHEP::mm, R*CLHEP::mm, hz,
                                    k * CLHEP::halfpi, CLHEP::halfpi));
        offsets.push_back(G4ThreeVector(sx[k]*f1*CLHEP::mm, sy[k]*f2*CLHEP::mm, 0));
      }
      return;
    }

    // shape 0: plain box, or box minus a rectangular bore
    G4VSolid* s = new G4Box(nm + "_out",
                            m.W1/2*CLHEP::mm, m.W2/2*CLHEP::mm, hz);
    if (m.wall > 0.0) {
      G4Box* bore = new G4Box(nm + "_bore",
                              (m.W1/2 - m.wall)*CLHEP::mm,
                              (m.W2/2 - m.wall)*CLHEP::mm, hz + 1.0*CLHEP::mm);
      s = new G4SubtractionSolid(nm, s, bore);
    }
    solids.push_back(s);
    offsets.push_back(G4ThreeVector(0, 0, 0));
  }


